const empty = (title: string, text: string) => `<div class="empty"><h3>${e(title)}</h3><p>${e(text)}</p></div>`;
const table = (columns: string[], rows: string[], label: string) => `<div class="table-wrap" tabindex="0" role="region" aria-label="${e(label)}"><table class="record-table"><thead><tr>${columns.map(column => `<th scope="col">${e(column)}</th>`).join('')}</tr></thead><tbody>${rows.length ? rows.join('') : `<tr><td class="empty-cell" colspan="${columns.length}">${empty('Nothing to show yet', 'Recorded activity will appear here.')}</td></tr>`}</tbody></table></div>`;
const td = (label: string, html: string, classes = '') => `<td data-label="${e(label)}" class="${classes}">${html}</td>`;
const nameOf = (id?: number | null) => { const s = snapshot(); return s.staff_directory?.find(staff => staff.id === id)?.name || s.cashiers.find(staff => staff.id === id)?.name || (s.staff.id === id ? s.staff.name : `Staff #${id ?? 'unknown'}`); };
const roleOf = (id: number) => { const s = snapshot(); return s.staff_directory?.find(staff => staff.id === id)?.role || (s.staff.id === id ? s.staff.role : s.cashiers.find(staff => staff.id === id)?.role); };
const orderNumber = (order: Order) => `ORD-${order.id ? String(order.id).padStart(6, '0') : order.reference.slice(0, 8).toUpperCase()}`;
const orderStatus = (order: Order) => ({ preparing: 'Preparing', ready: 'Ready', out_for_delivery: 'Out for delivery', completed: order.fulfillment === 'delivery' ? 'Delivered' : 'Picked up', cancelled: 'Cancelled' })[order.status];
const ownsOrder = (order: Order) => order.user_id === snapshot().staff.id || (roleOf(order.user_id) === 'admin' && order.assigned_cashier_id === snapshot().staff.id);
const editableHere = (order: Order) => snapshot().staff.role === 'cashier' && ownsOrder(order) && order.device_id === snapshot().device.id && !['completed', 'cancelled'].includes(order.status);
const freeStock = (product: Product) => product.stock - product.reserved - product.allocated;
function parseMoney(value: string): number { if (!/^\d{1,7}(\.\d{1,2})?$/.test(value)) throw new Error('Enter an amount with at most two decimal places.'); const [whole, fraction = ''] = value.split('.'); const result = Number(whole) * 100 + Number(fraction.padEnd(2, '0')); if (!Number.isSafeInteger(result) || result > 999999999) throw new Error('The amount is too large.'); return result; }
const uuid = () => crypto.randomUUID();
const receiptNumber = (reference: string) => `S-${snapshot().device.id.slice(0, 8)}-${reference.slice(0, 12)}`;
const lines = (): Line[] => [...cart.values()].map(line => ({ product_id: line.product_id, quantity: line.quantity, price_version_id: line.price_version_id }));
const subtotal = () => [...cart.values()].reduce((sum, line) => sum + line.quantity * line.price_cents, 0);
const units = () => [...cart.values()].reduce((sum, line) => sum + line.quantity, 0);
const total = () => subtotal() + (pos.fulfillment === 'delivery' ? safeMoney(pos.delivery_fee) : 0);
const safeMoney = (value: string) => { try { return parseMoney(value); } catch { return 0; } };
function available(product: Product, version?: string | null): number { const s = snapshot(); if (product.kind === 'service') return s.price_grants.some(grant => grant.product_id === product.id && (!version || grant.price_version_id === version)) ? 999 : 0; return s.allocations.find(allocation => allocation.product_id === product.id && (!version || allocation.price_version_id === version))?.remaining || 0; }
function grantFor(product: Product) { const s = snapshot(); const version = product.kind === 'product' ? s.allocations.find(allocation => allocation.product_id === product.id)?.price_version_id : product.price_version_id; return s.price_grants.find(grant => grant.product_id === product.id && grant.price_version_id === version) || (product.kind === 'service' ? s.price_grants.find(grant => grant.product_id === product.id && grant.kind === 'service') : undefined); }
function route() { return decodeURIComponent(location.hash.slice(1)) || (snapshot().staff.role === 'admin' ? 'overview' : 'pos'); }
function go(next: string) { closeDialog(); location.hash = next; render(); document.getElementById('main')?.focus({ preventScroll: true }); }
function report(text: string, error = false) { feedback = { text, error }; }
function capturePos() {
  const form = document.getElementById('pos-form') as HTMLFormElement | null; if (!form || form.dataset.completed) return;
  const data = new FormData(form);
  for (const name of ['fulfillment', 'channel', 'payment_plan', 'payment_method', 'amount', 'payment_reference'] as const) if (data.has(name)) pos[name] = String(data.get(name) || '');
  if (form.querySelector('[name=payment_verified]')) pos.payment_verified = data.get('payment_verified') === 'on';
}
function render() {
  if (!backend || !getCloudConfig().configured) { renderAuth(true); return; }
  if (!store?.snapshot || !authorized) { renderAuth(false); return; }
  capturePos();
  const menuWasOpen = (document.getElementById('store-menu') as HTMLDialogElement | null)?.open;
  const focus = document.activeElement as HTMLElement | null;
  const actionFocus = focus?.dataset.action ? `[data-action="${CSS.escape(focus.dataset.action)}"]${focus.dataset.id ? `[data-id="${CSS.escape(focus.dataset.id)}"]` : ''}${focus.dataset.ref ? `[data-ref="${CSS.escape(focus.dataset.ref)}"]` : ''}` : undefined;
  const focusId = focus?.id, selection = focus instanceof HTMLInputElement && ['text', 'search', 'email', 'tel'].includes(focus.type) ? [focus.selectionStart, focus.selectionEnd] : null;
  const s = snapshot(); const admin = s.staff.role === 'admin'; let current = route();
  if ((!admin && ['overview', 'inventory', 'accounts', 'allocations'].includes(current)) || (admin && current === 'pos')) current = admin ? 'overview' : 'pos';
  const links = admin ? [['overview', 'Overview', 'overview'], ['inventory', 'Inventory', 'inventory'], ['accounts', 'Cashier accounts', 'pos'], ['allocations', 'Stock allocations', 'device'], ['orders', 'Orders review', 'delivery'], ['sales', 'Sales reports', 'sales']] : [['pos', 'Point of sale', 'pos'], ['orders', 'Orders & delivery', 'delivery'], ['sales', 'My sales & receipts', 'sales']];
  links.push(['device', 'Device & sync', 'sync']);
  const navigation = `<nav aria-label="Store navigation">${links.map(([key, label, symbol]) => `<a class="nav-link${current === key || (current.startsWith('order/') && key === 'orders') || (current.startsWith('receipt/') && key === 'sales') ? ' current' : ''}" href="#${key}" data-route="${key}" ${current === key ? 'aria-current="page"' : ''}>${icon(symbol)}${label}</a>`).join('')}</nav>`;
  const profile = `<div class="profile"><span class="avatar" aria-hidden="true">${e(s.staff.name.slice(0, 1))}</span><div><strong>${e(s.staff.name)}</strong><small>${admin ? 'Admin' : 'Cashier'}</small></div></div><button type="button" class="signout" data-action="signout"${disabled(!store.canSignOut || busy)}>Sign out ${icon('logout')}</button>`;
  const title = links.find(link => link[0] === current)?.[1] || (current.startsWith('receipt/') ? 'Receipt' : 'Order details');
  document.title = `${title} · Smart School Supplies`;
  document.body.dataset.workspaceRole = s.staff.role;
  const content = current === 'overview' ? overview() : current === 'pos' ? pointOfSale() : current === 'inventory' ? inventory() : current === 'accounts' ? accounts() : current === 'allocations' ? allocations() : current === 'orders' ? orders() : current === 'sales' ? sales() : current.startsWith('order/') ? orderDetail(current.slice(6)) : current.startsWith('receipt/') ? receipt(current.slice(8)) : device();
  app.innerHTML = `<div class="workspace"><aside class="sidebar no-print">${brand()}<p class="nav-label">${admin ? 'ADMIN' : 'CASHIER'} WORKSPACE</p>${navigation}<div class="sidebar-footer"><p class="device-caption">${icon('device', 16)} ${e(s.device.name)}</p>${profile}</div></aside><div class="workspace-body"><header class="topbar no-print"><button type="button" class="button secondary menu-button" data-action="menu" aria-haspopup="dialog" aria-controls="store-menu">${icon('menu')}Menu</button><div class="topbar-context"><small>${admin ? 'Admin' : 'Cashier'} workspace</small><strong>${e(title)}</strong></div><div class="topbar-actions" id="sync-status">${syncStatus()}</div></header><main id="main" class="main" tabindex="-1">${store?.requiresRefresh ? '<div class="notice error" role="alert">Refresh required before recording changes. Reconnect and select Sync now to confirm the result of the previous shared action.</div>' : ''}${feedback.text ? `<div class="notice ${feedback.error ? 'error' : 'success'}" role="${feedback.error ? 'alert' : 'status'}">${e(feedback.text)}</div>` : ''}${content}</main></div></div><dialog id="store-menu" class="menu-dialog" aria-labelledby="menu-title"><div class="dialog-heading"><div><span class="eyebrow">${admin ? 'ADMIN' : 'CASHIER'} WORKSPACE</span><h2 id="menu-title">Store menu</h2></div><button type="button" class="icon-button" data-action="close-menu" aria-label="Close store menu">${icon('close')}</button></div>${navigation}${profile}</dialog><dialog id="action-dialog" aria-labelledby="dialog-title"></dialog>`;
  const active = focusId ? document.getElementById(focusId) : actionFocus ? [...document.querySelectorAll<HTMLElement>(actionFocus)].find(item => item.getClientRects().length) : undefined;
  if (active?.getClientRects().length) { active.focus({ preventScroll: true }); if (selection && active instanceof HTMLInputElement) active.setSelectionRange(selection[0], selection[1]); }
  document.getElementById('store-menu')?.addEventListener('close', () => { const trigger = document.querySelector<HTMLButtonElement>('[data-action=menu]'); if (trigger?.getClientRects().length) trigger.focus({ preventScroll: true }); else revealNavigation(); });
  if (menuWasOpen && window.matchMedia('(max-width:1100px)').matches) (document.getElementById('store-menu') as HTMLDialogElement).showModal();
}
function revealNavigation() { const link = document.querySelector<HTMLAnchorElement>('.sidebar .current'); if (!link) return; link.focus({preventScroll: true}); const nav = link.closest('nav')!; const bounds = link.getBoundingClientRect(), region = nav.getBoundingClientRect(); if (bounds.top < region.top + 6) nav.scrollTop -= region.top + 6 - bounds.top; else if (bounds.bottom > region.bottom - 6) nav.scrollTop += bounds.bottom - region.bottom + 6; }
function syncStatus() { const s = snapshot(); return `<span class="badge ${online() && !autoSyncPaused ? 'positive' : 'pending'}">${online() ? (autoSyncPaused ? 'Connection interrupted' : 'Online') : 'Offline'}</span>${routeLink('device', `<span class="queue-count">${store!.pendingCount}</span> pending${store!.reviewCount ? ` · ${store!.reviewCount} review` : ''}`, 'text-link')}<small class="last-sync">Last sync ${e(when(s.fetched_at))}</small>${button('sync', `${icon('sync')} Sync now`, 'secondary', disabled(!online() || busy))}${installPrompt ? button('install', 'Install app') : ''}`; }
function renderAuth(setup: boolean) {
  const cached = store?.snapshot || lastKnown || (store?.preparedIdentity ? {staff: {email: store.preparedIdentity.email}} : null); const config = getCloudConfig();
  const finishing = !!store?.signOutPending;
  app.innerHTML = `<main id="main" class="auth-page" tabindex="-1"><div class="auth-shell"><section class="auth-story">${brand()}<div><h1>Your store,<br><em>ready anywhere.</em></h1><p>Dedicated Admin and Cashier workspaces. Prepare your device online, then keep authorized work moving when the connection drops.</p></div><img class="auth-banner" src="/assets/banner.png" width="1536" height="1024" alt="Smart School Supplies: school essentials, printing, photocopying, and scanning."></section><section class="auth-form"><span class="eyebrow">STAFF ACCESS</span><h2>${setup ? 'Connect your store' : finishing ? 'Finish signing out' : cached ? 'Restore your online session' : 'Staff sign in'}</h2>${store?.requiresRefresh ? '<div class="notice error" role="alert">Refresh required before recording changes. Reconnect and select Sync now to confirm the result of the previous shared action.</div>' : ''}${feedback.text ? `<div class="notice ${feedback.error ? 'error' : 'success'}" role="alert">${e(feedback.text)}</div>` : ''}${setup ? `<p>The cloud connection has not been configured.</p>${config.error ? `<p class="notice error">${e(config.error)}</p>` : ''}<ol class="setup-list"><li>The project administrator must configure the Supabase project URL and public publishable key, then rebuild the staff app.</li><li>Create the first Admin privately in Supabase and complete the secured staff bootstrap.</li><li>Sign in online to prepare each staff device before using it offline.</li></ol><a class="button secondary" href="/">Browse the public catalog</a>` : finishing ? `<p>Sign out was interrupted. This device's private workspace stays locked until cleanup finishes. Reconnect and finish signing out before preparing the device again.</p>${button('signout', 'Finish sign out', 'full', disabled(!online() || busy || !store?.canSignOut))}` : `<p>${cached ? 'Use the same staff account. If Admin changed your email, enter its current address. Your saved changes stay on this device.' : 'Internet is required for your first sign-in on this device.'}</p>
    <form id="signin-form"><div><label for="signin-email">Email address</label><input id="signin-email" name="email" type="email" autocomplete="username" required value="${e(cached?.staff.email || '')}"></div><div><label for="signin-password">Password</label><input id="signin-password" name="password" type="password" autocomplete="current-password" required></div>${cached ? '' : '<div><label for="device-name">Device name</label><input id="device-name" name="device_name" maxlength="80" placeholder="e.g. Counter tablet" required autocomplete="off"></div>'}<button type="submit" class="button full"${disabled(!online() || busy)}>${busy ? 'Preparing device…' : cached ? 'Restore session' : 'Sign in & prepare device'}</button></form>`}${!setup ? `<p class="auth-help">${online() ? 'Staff accounts are created by Admin. No public registration.' : 'You are offline. Reconnect to sign in or reauthenticate.'}<br><a href="/">Open the customer catalog</a></p>` : ''}</section></div></main>`;
}
function overview() { const s = snapshot(); const today = day(new Date().toISOString()); const paid = s.sales.filter(sale => day(sale.created_at) === today); const open = s.orders.filter(order => !['completed', 'cancelled'].includes(order.status)); return `${heading('Your store today', 'Review recorded sales, customer orders, stock, and changes awaiting synchronization.', routeLink('inventory', `${icon('inventory')} Manage inventory`, 'button'))}<section class="metrics" aria-label="Store metrics"><article class="metric featured"><span>Sales today</span><strong>${money(paid.reduce((sum, sale) => sum + sale.total_cents, 0))}</strong><small>Includes device-pending sales shown below</small></article><article class="metric"><span>Transactions today</span><strong>${paid.length}</strong><small>Recorded sales · not net profit</small></article><article class="metric"><span>Open orders</span><strong>${open.length}</strong><small>Preparing, ready, or out for delivery</small></article><article class="metric"><span>Needs attention</span><strong>${s.products.filter(product => product.active && product.kind !== 'service' && freeStock(product) <= product.reorder_level).length}</strong><small>Free stock at or below reorder level</small></article></section><section class="panel"><div class="panel-heading"><div><h2>Stock protection</h2><p>Stock reserved for orders or allocated to devices is not freely available.</p></div>${routeLink('allocations', 'Manage allocations', 'text-link')}</div>${table(['Item', 'Stock', 'Reserved', 'Allocated', 'Free'], s.products.filter(product => product.kind !== 'service').map(product => `<tr>${td('Item', `<strong>${e(product.name)}</strong>`, 'primary-cell')}${td('Stock', String(product.stock))}${td('Reserved', String(product.reserved))}${td('Allocated', String(product.allocated))}${td('Free', String(freeStock(product)))}</tr>`), 'Protected stock')}</section><section class="panel"><div class="panel-heading"><h2>Recent transactions</h2>${routeLink('sales', 'View sales reports', 'text-link')}</div>${saleTable(s.sales.slice().sort((a, b) => b.created_at.localeCompare(a.created_at)).slice(0, 8))}</section>`; }
function saleTable(records: Sale[]) { return table(['Receipt', 'Recorded', 'Payment', 'Recorder / collector', 'Total', 'Status', 'Actions'], records.map(sale => `<tr>${td('Receipt', `<strong>${e(sale.receipt_number)}</strong>`, 'primary-cell')}${td('Recorded', e(when(sale.created_at)))}${td('Payment', sale.payment_method === 'gcash' ? 'GCash · staff verified' : 'Cash')}${td('Recorder / collector', `${e(nameOf(sale.user_id))}<small class="cell-sub">Payment by ${e(nameOf(sale.paid_by))}</small>`)}${td('Total', money(sale.total_cents), 'money')}${td('Status', statusBadge(sale.local_status))}${td('Actions', routeLink(`receipt/${sale.reference}`, 'View receipt'), 'actions-cell')}</tr>`), 'Sales and receipts'); }
function sales() { const s = snapshot(); const records = s.sales.filter(sale => (!salesFrom || day(sale.created_at) >= salesFrom) && (!salesTo || day(sale.created_at) <= salesTo)).sort((a, b) => b.created_at.localeCompare(a.created_at)); return `${heading(s.staff.role === 'admin' ? 'Sales reports' : 'My sales & receipts', s.staff.role === 'admin' ? 'Review store transactions. Pending and reviewed changes are labeled separately.' : 'Your recorded sales and Admin-order payments you collected.', s.staff.role === 'cashier' ? routeLink('pos', 'New sale', 'button') : '')}<section class="metrics"><article class="metric featured"><span>Recorded total</span><strong>${money(records.reduce((sum, sale) => sum + sale.total_cents, 0))}</strong><small>Includes pending device records</small></article><article class="metric"><span>Confirmed cloud total</span><strong>${money(records.filter(sale => !sale.local_status).reduce((sum, sale) => sum + sale.total_cents, 0))}</strong><small>Synced records in selected period</small></article><article class="metric"><span>Cash payments</span><strong>${money(records.filter(sale => sale.payment_method === 'cash').reduce((sum, sale) => sum + sale.total_cents, 0))}</strong><small>Recorded cash sales</small></article><article class="metric"><span>Verified GCash</span><strong>${money(records.filter(sale => sale.payment_method === 'gcash').reduce((sum, sale) => sum + sale.total_cents, 0))}</strong><small>Manual staff verification</small></article></section><section class="panel"><div class="panel-heading"><form class="filter-bar" id="sales-filter"><label for="sales-from">From<input id="sales-from" name="from" type="date" value="${e(salesFrom)}"></label><label for="sales-to">To<input id="sales-to" name="to" type="date" value="${e(salesTo)}"></label><button class="button secondary" type="submit">Apply dates</button>${button('reset-sales', 'All dates')}</form></div>${saleTable(records)}</section>`; }
function receipt(reference: string) { const s = snapshot(); const sale = [...s.sales, ...(s.receipts || [])].find(record => record.reference === reference); if (!sale) return `${heading('Receipt unavailable', 'This receipt is not in your permitted device records.')}${routeLink('sales', 'Back to sales')}`; const order = s.orders.find(record => record.sale_reference === sale.reference); return `${heading('Recorded receipt', 'Review the saved transaction and payment details.', `<div class="actions">${button('print', 'Print receipt')}${routeLink('sales', 'Back to sales')}</div>`)}<article class="panel receipt"><header class="receipt-head"><img src="/assets/logo.png" width="213" height="184" alt=""><h2>Smart School Supplies</h2><p>School essentials & academic services</p><h3>${e(sale.receipt_number)}</h3>${statusBadge(sale.local_status)}</header>${sale.local_status ? '<p class="notice pending">This transaction is saved on this device. It is not confirmed in the cloud until synchronization succeeds.</p>' : ''}<dl class="details"><div><dt>Recorded</dt><dd>${e(when(sale.created_at))}</dd></div><div><dt>Original recorder</dt><dd>${e(nameOf(sale.user_id))}</dd></div><div><dt>Payment recorded by</dt><dd>${e(nameOf(sale.paid_by))}</dd></div><div><dt>Channel</dt><dd>${e(sale.channel)}</dd></div><div><dt>Payment</dt><dd>${sale.payment_method === 'gcash' ? 'GCash · staff verified' : 'Cash'}</dd></div>${sale.payment_reference ? `<div><dt>GCash reference</dt><dd>${e(sale.payment_reference)}</dd></div>` : ''}${order ? `<div><dt>Order</dt><dd>${e(orderNumber(order))} · ${e(order.fulfillment)}</dd></div>` : ''}</dl><table><thead><tr><th>Item</th><th class="align-right">Amount</th></tr></thead><tbody>${sale.items.map(line => `<tr><td><strong>${e(line.name)}</strong><small class="cell-sub">${line.quantity} × ${money(line.price_cents)}</small></td><td class="align-right money">${money(line.total_cents)}</td></tr>`).join('')}</tbody></table><div class="breakdown"><span>Items subtotal</span><strong>${money(sale.subtotal_cents)}</strong></div><div class="breakdown"><span>Delivery fee</span><strong>${money(sale.delivery_fee_cents)}</strong></div><div class="total-row"><span>Total</span><strong>${money(sale.total_cents)}</strong></div><div class="breakdown"><span>${sale.payment_method === 'gcash' ? 'Verified amount' : 'Cash received'}</span><strong>${money(sale.cash_cents)}</strong></div>${sale.payment_method === 'cash' ? `<div class="breakdown"><span>Change</span><strong>${money(sale.change_cents)}</strong></div>` : ''}<footer class="receipt-foot">Thank you for shopping with us.<br>Sales acknowledgment · not a BIR-registered invoice</footer></article>`; }
function paymentFields(method = 'cash', amount = '', reference = '', verified = false, prefix = 'pos') { return `<div class="payment-grid"><label for="${prefix}-payment-method">Payment method<select id="${prefix}-payment-method" name="payment_method"><option value="cash"${selected(method === 'cash')}>Cash</option><option value="gcash"${selected(method === 'gcash')}>GCash · staff verified</option></select></label><label for="${prefix}-amount">${method === 'gcash' ? 'Verified GCash amount' : 'Cash received'} (₱)<input id="${prefix}-amount" name="amount" type="number" step="0.01" min="0" max="9999999.99" value="${e(amount)}" required></label></div><div class="gcash-fields"${method !== 'gcash' ? ' hidden' : ''}><label for="${prefix}-reference">GCash reference<input id="${prefix}-reference" name="payment_reference" value="${e(reference)}" minlength="6" maxlength="80" pattern="[A-Za-z0-9\\x2D]{6,80}"${method === 'gcash' ? ' required' : ' disabled'} autocomplete="off"></label><label class="checkbox-label"><input type="checkbox" name="payment_verified"${verified ? ' checked' : ''}${method === 'gcash' ? ' required' : ' disabled'}> I checked the store account and verified this payment.</label></div>`; }
function posOptions() { const order = pos.fulfillment !== 'counter'; return `<div class="pos-options"><label for="pos-fulfillment">Fulfillment<select id="pos-fulfillment" name="fulfillment"><option value="counter"${selected(!order)}>Counter sale</option><option value="pickup"${selected(pos.fulfillment === 'pickup')}>Store pickup</option><option value="delivery"${selected(pos.fulfillment === 'delivery')}>Delivery</option></select></label><label for="pos-channel">Order channel<select id="pos-channel" name="channel"><option value="walk-in"${selected(pos.channel === 'walk-in')}>Walk-in</option><option value="messenger"${selected(pos.channel === 'messenger')}>Messenger (confirmed)</option></select></label>${order ? `<label for="pos-payment-plan">Payment timing<select id="pos-payment-plan" name="payment_plan"><option value="prepaid"${selected(pos.payment_plan === 'prepaid')}>Prepaid</option><option value="collection"${selected(pos.payment_plan === 'collection')}>On pickup / delivery</option></select></label>${button('customer-details', `${icon('delivery')} Customer details`, 'secondary')}` : ''}</div>`; }
function pointOfSale() {
  const s = snapshot(); const products = s.products.filter(product => product.active && product.id > 0 && product.kind !== 'consumable' && (typeFilter === 'all' || product.kind === typeFilter) && `${product.name} ${product.sku} ${product.category}`.toLowerCase().includes(searchText.toLowerCase()));
  const order = pos.fulfillment !== 'counter'; const paidNow = !order || pos.payment_plan === 'prepaid';
  const cards = products.map(product => { const grant = grantFor(product); const count = available(product, grant?.price_version_id); return `<button type="button" class="pos-card" data-action="add-product" data-id="${product.id}"${disabled(!grant || count === 0 || (cart.get(product.id)?.quantity || 0) >= Math.min(999, count))}><small>${e(product.category)}</small><strong>${e(grant?.name || product.name)}</strong><span class="pos-price">${money(grant?.price_cents ?? product.price_cents)}</span><span class="pos-stock">${product.kind === 'service' ? (grant ? 'Service access ready' : 'Connect to refresh service access') : `${count} available on this device`}</span><span class="add-symbol" aria-hidden="true">+</span></button>`; }).join('');
  return `${heading('Point of sale', 'Choose supplies or services. Record a sale or a confirmed customer order.', routeLink('orders', `${icon('delivery')} <span class="desktop-label">Orders & delivery</span><span class="phone-label">Orders</span>`))}<div class="pos-view-switcher" role="tablist" aria-label="Point of sale view"><button type="button" id="products-tab" role="tab" aria-selected="${posPane === 'products'}" aria-controls="product-browser" data-action="pos-products" tabindex="${posPane === 'products' ? 0 : -1}">${icon('product')} Products</button><button type="button" id="sale-tab" role="tab" aria-selected="${posPane === 'sale'}" aria-controls="checkout-basket" data-action="pos-sale" tabindex="${posPane === 'sale' ? 0 : -1}">${icon('basket')} Current sale · ${units()}<strong>${money(total())}</strong></button></div><form id="pos-form" class="pos-layout" data-pane="${posPane}"><section class="pos-products" id="product-browser" aria-label="Select products and services"><div class="browse-toolbar"><label class="sr-only" for="pos-search">Search products or SKU</label><input type="search" id="pos-search" placeholder="Search an item or SKU…" value="${e(searchText)}" autocomplete="off"><div class="tabs" role="group" aria-label="Item type">${[['all', 'All items'], ['product', 'Supplies'], ['service', 'Services']].map(([kind, label]) => `<button type="button" data-action="pos-filter" data-filter="${kind}" aria-pressed="${typeFilter === kind}">${label}</button>`).join('')}</div></div><p class="result-count" role="status">${products.length} items · device allocations protect shared stock</p>${narrow() ? '' : posOptions()}<div class="pos-grid" id="pos-products" tabindex="0" role="region" aria-label="Available products">${cards}</div>${!products.length ? empty('No items found', 'Try another search or ask Admin to prepare your device’s stock.') : ''}</section><section class="panel checkout-panel" id="checkout-basket" aria-labelledby="basket-heading" tabindex="-1"><div class="panel-heading"><div><h2 id="basket-heading">Current sale</h2><small>${units()} items</small></div><div class="record-actions"><button type="button" class="text-button return-products" data-action="pos-products">${icon('back')} Products</button><button type="button" class="text-button" data-action="clear-cart"${disabled(!cart.size)}>Clear</button></div></div>${narrow() ? posOptions() : ''}<div class="checkout-scroll" tabindex="0" role="region" aria-label="Basket items">${cart.size ? [...cart.values()].map(line => `<div class="cart-line"><div><strong>${e(line.name)}</strong><small>${money(line.price_cents)} each</small></div><span class="money">${money(line.quantity * line.price_cents)}</span><div class="quantity-control"><button type="button" data-action="cart-minus" data-id="${line.product_id}" aria-label="Decrease ${e(line.name)}">−</button><input id="cart-quantity-${line.product_id}" name="quantity-${line.product_id}" type="number" min="1" max="${Math.min(999, available(getProduct(line.product_id), line.price_version_id))}" value="${line.quantity}" data-cart-id="${line.product_id}" aria-label="Quantity of ${e(line.name)}"><button type="button" data-action="cart-plus" data-id="${line.product_id}"${disabled(line.quantity >= Math.min(999, available(getProduct(line.product_id), line.price_version_id)))} aria-label="Increase ${e(line.name)}">+</button><button type="button" class="remove" data-action="cart-remove" data-id="${line.product_id}" aria-label="Remove ${e(line.name)}">Remove</button></div></div>`).join('') : empty('Start a new sale', 'Choose a product or service to start.')}</div><div class="pos-payment">${paidNow ? paymentFields(pos.payment_method, pos.amount, pos.payment_reference, pos.payment_verified) : '<p class="help">Payment on collection. Confirmed quantities stay reserved until payment is recorded.</p>'}</div><div class="checkout-footer">${order ? `<div class="breakdown"><span>Items subtotal</span><strong>${money(subtotal())}</strong></div><div class="breakdown"><span>Delivery fee</span><strong>${money(pos.fulfillment === 'delivery' ? safeMoney(pos.delivery_fee) : 0)}</strong></div>` : ''}<div class="total-row"><span>Total due</span><strong id="cart-total">${money(total())}</strong></div>${paidNow && pos.payment_method === 'cash' ? `<div class="breakdown"><span>Change</span><strong id="cart-change">${money(Math.max(0, safeMoney(pos.amount) - total()))}</strong></div>` : ''}<button type="submit" id="complete-sale" class="button"${disabled(!cart.size || busy || store!.requiresRefresh)}>${order ? 'Confirm order' : 'Complete sale'} →</button><p class="help">Saved changes remain pending until cloud synchronization succeeds.</p></div></section></form><button type="button" class="button mobile-sale-bar no-print" data-action="pos-sale"${posPane === 'sale' ? ' hidden' : ''}><span>Current sale · ${units()} items</span><strong>${money(total())}</strong> →</button>`;
}
function inventory() { const s = snapshot(); return `${heading('Inventory', 'Manage items and physical stock without consuming reserved or allocated quantities.', button('new-product', `${icon('plus')} Add item`, ''))}<div class="tabs" role="group" aria-label="Inventory view"><button type="button" data-action="inventory-items" aria-pressed="${inventoryTab === 'items'}">Items</button><button type="button" data-action="inventory-movements" aria-pressed="${inventoryTab === 'movements'}">Stock movements</button></div><section class="panel">${inventoryTab === 'items' ? `<div class="panel-heading"><label for="inventory-search">Search inventory<input id="inventory-search" type="search" value="${e(searchText)}" placeholder="Name, SKU, or category"></label><span class="badge">${s.products.length} items</span></div>${table(['Item / SKU', 'Category / type', 'Price', 'Stock protection', 'Status', 'Actions'], s.products.filter(product => `${product.name} ${product.sku} ${product.category}`.toLowerCase().includes(searchText.toLowerCase())).map(product => `<tr>${td('Item / SKU', `<strong>${e(product.name)}</strong><small class="cell-sub">${e(product.sku)}${product.id < 0 ? ' · pending new item' : ''}</small>`, 'primary-cell')}${td('Category / type', `${e(product.category)}<small class="cell-sub">${e(product.kind === 'consumable' ? 'Internal supply' : product.kind)}</small>`)}${td('Price', product.kind === 'consumable' ? 'Not sold' : money(product.price_cents))}${td('Stock protection', product.kind === 'service' ? 'Service' : `<strong>${freeStock(product)} free</strong><small class="cell-sub">${product.stock} stock · ${product.reserved} reserved · ${product.allocated} allocated</small>`)}${td('Status', `<span class="badge ${product.active ? 'positive' : ''}">${product.active ? 'Active' : 'Inactive'}</span>`)}${td('Actions', `<div class="record-actions">${button('edit-product', 'Edit', 'secondary', `data-id="${product.id}"`)}${product.kind !== 'service' ? button('stock-movement', 'Stock movement', 'secondary', `data-id="${product.id}"`) : ''}</div>`, 'actions-cell')}</tr>`), 'Inventory items')}` : `<div class="panel-heading"><div><h2>Stock movements</h2><p>Opening stock, received supplies, sales, and recorded usage</p></div></div>${table(['Item', 'Quantity', 'Reason', 'Staff', 'Recorded'], s.movements.map(movement => `<tr>${td('Item', e(s.products.find(product => product.id === movement.product_id)?.name || `Item #${movement.product_id}`), 'primary-cell')}${td('Quantity', `${movement.quantity > 0 ? '+' : ''}${movement.quantity}`)}${td('Reason', e(movement.reason))}${td('Staff', e(nameOf(movement.user_id)))}${td('Recorded', e(when(movement.created_at)))}</tr>`), 'Stock movements')}`}</section>`; }
function accounts() { const s = snapshot(); return `${heading('Cashier accounts', 'Manage cashier access and preserve transaction history.', button('new-cashier', `${icon('plus')} Add cashier`, '', disabled(!cleanOnline())))}<p class="notice">Account changes require internet and a fully synced device. Disable accounts instead of deleting transaction history.</p><section class="panel">${table(['Cashier', 'Login email', 'Access', 'Actions'], s.cashiers.filter(staff => staff.role === 'cashier').map(staff => `<tr>${td('Cashier', `<strong>${e(staff.name)}</strong>`, 'primary-cell')}${td('Login email', e(staff.email))}${td('Access', `<span class="badge ${staff.active ? 'positive' : 'review'}">${staff.active ? 'Enabled' : 'Disabled'}</span>`)}${td('Actions', `<div class="record-actions">${button('edit-cashier', 'Manage account', 'secondary', `data-id="${staff.id}"${disabled(!cleanOnline())}`)}${button('cashier-password', 'Reset password', 'secondary', `data-id="${staff.id}"${disabled(!cleanOnline())}`)}${button('cashier-active', staff.active ? 'Disable' : 'Enable', staff.active ? 'danger' : 'secondary', `data-id="${staff.id}"${disabled(!cleanOnline())}`)}</div>`, 'actions-cell')}</tr>`), 'Cashier accounts')}</section>`; }
function allocations() { const s = snapshot(); const eligible = s.devices.filter(device => device.active && s.cashiers.some(staff => staff.id === device.staff_id && staff.active && staff.role === 'cashier')); const products = s.products.filter(product => product.id > 0 && product.kind === 'product' && product.active); return `${heading('Stock allocations', 'Set aside stock for cashier devices so disconnected sales cannot consume the same units twice.')}<p class="notice">Allocating stock requires internet and a fully synced Admin device. Only the receiving cashier can return unused stock from their own synced device.</p><section class="panel"><div class="panel-heading"><h2>Allocate to a prepared cashier device</h2></div><div class="panel-body">${eligible.length && products.length ? `<form id="allocation-form" class="form-stack"><div class="form-grid"><div><label for="allocation-device">Cashier device</label><select id="allocation-device" name="device_id" required><option value="">Choose a device</option>${eligible.map(device => `<option value="${e(device.id)}">${e(nameOf(device.staff_id))} · ${e(device.name)}</option>`).join('')}</select></div><div><label for="allocation-product">Product</label><select id="allocation-product" name="product_id" required><option value="">Choose a product</option>${products.map(product => `<option value="${product.id}"${disabled(freeStock(product) <= 0)}>${e(product.name)} · ${freeStock(product)} free</option>`).join('')}</select></div><div><label for="allocation-quantity">Quantity</label><input id="allocation-quantity" name="quantity" type="number" min="1" max="1000000" required></div></div><button type="submit" class="button"${disabled(!cleanOnline())}>Allocate stock</button></form>` : empty('No allocation target available', 'A cashier must sign in online to prepare a device, and the inventory must contain an active product.')}</div></section><section class="panel"><div class="panel-heading"><h2>Prepared devices</h2></div>${table(['Device', 'Staff', 'Access'], s.devices.map(device => `<tr>${td('Device', `<strong>${e(device.name)}</strong><small class="cell-sub">${e(device.id.slice(0, 8))}</small>`, 'primary-cell')}${td('Staff', e(nameOf(device.staff_id)))}${td('Access', device.active ? 'Active' : 'Inactive')}</tr>`), 'Prepared devices')}</section>`; }
function orders() { const s = snapshot(); const admin = s.staff.role === 'admin'; const records = s.orders.filter(order => (admin || ownsOrder(order)) && (orderFilter === 'all' || (orderFilter === 'open' ? !['completed', 'cancelled'].includes(order.status) : order.status === orderFilter)) && `${order.customer_name} ${orderNumber(order)}`.toLowerCase().includes(orderSearch.toLowerCase())).sort((a, b) => b.created_at.localeCompare(a.created_at)); return `${heading(admin ? 'Orders review' : 'Orders & delivery', admin ? 'Review orders and hand off unfinished Admin-origin orders to an active cashier.' : 'Prepare your own and assigned orders, collect payments, and complete handovers.', admin ? '' : routeLink('pos', 'New order', 'button'))}<details class="review-details"><summary>How pickup & delivery orders work</summary><p>Cashiers confirm Messenger or walk-in orders in POS. An order must be claimed by one device before offline corrections, payment, or fulfillment updates. Prepaid payment is recorded at creation; collection payment is recorded before the final handover.</p></details><section class="panel"><div class="panel-heading"><label for="order-search">Customer or order<input id="order-search" type="search" value="${e(orderSearch)}" placeholder="Search orders"></label><label for="order-filter">Status<select id="order-filter">${[['open', 'Open orders'], ['all', 'All orders'], ['preparing', 'Preparing'], ['ready', 'Ready'], ['out_for_delivery', 'Out for delivery'], ['completed', 'Completed'], ['cancelled', 'Cancelled']].map(([value, label]) => `<option value="${value}"${selected(orderFilter === value)}>${label}</option>`).join('')}</select></label></div>${table(['Order / customer', 'Fulfillment', 'Status', 'Payment', 'Device claim', 'Actions'], records.map(order => `<tr>${td('Order / customer', `<strong>${e(orderNumber(order))}</strong><small class="cell-sub">${e(order.customer_name)}</small><small class="cell-sub">Recorder: ${e(nameOf(order.user_id))}${order.assigned_cashier_id ? ` · assigned to ${e(nameOf(order.assigned_cashier_id))}` : ''}</small>`, 'primary-cell')}${td('Fulfillment', e(order.fulfillment))}${td('Status', `<span class="badge">${e(orderStatus(order))}</span> ${statusBadge(order.local_status)}`)}${td('Payment', `${order.sale_reference ? 'Paid' : 'Unpaid'}<small class="cell-sub">${money(order.total_cents)}</small>`)}${td('Device claim', order.device_id === s.device.id ? 'This device' : order.device_id ? 'Another device' : 'Not claimed')}${td('Actions', `<div class="record-actions">${routeLink(`order/${order.reference}`, 'View order')}${editableHere(order) && ['preparing', 'ready'].includes(order.status) ? button('edit-order', 'Edit order', 'secondary', `data-ref="${e(order.reference)}"`) : ''}</div>`, 'actions-cell')}</tr>`), 'Orders and delivery')}</section>`; }
function orderDetail(reference: string) {
  const s = snapshot(); const order = s.orders.find(record => record.reference === reference); if (!order) return `${heading('Order unavailable', 'This order is not in your permitted device records.')}${routeLink('orders', 'Back to orders')}`;
  const admin = s.staff.role === 'admin'; const active = !['completed', 'cancelled'].includes(order.status); const leased = order.device_id === s.device.id; const canWork = editableHere(order); const sequence = order.fulfillment === 'delivery' ? ['preparing', 'ready', 'out_for_delivery', 'completed'] : ['preparing', 'ready', 'completed']; const next = sequence[sequence.indexOf(order.status) + 1]; const handoff = admin && roleOf(order.user_id) === 'admin' && active;
  const mutationActions = canWork ? `<section class="panel"><div class="panel-heading"><h2>Next step</h2></div><div class="panel-body form-stack"><p class="help">${order.status === 'preparing' ? 'Prepare the supplies and requested services, then mark ready.' : order.status === 'ready' && order.fulfillment === 'delivery' ? 'Dispatch the prepared goods and record delivery progress.' : 'Verify the handover and record any collected payment before finishing.'}</p>${next ? button('order-status', next === 'ready' ? 'Mark ready' : next === 'out_for_delivery' ? 'Send out for delivery' : order.fulfillment === 'delivery' ? 'Mark delivered' : 'Mark picked up', '', `data-ref="${e(order.reference)}" data-status="${next}"${disabled(next === 'completed' && !order.sale_reference || busy)}`) : ''}${!order.sale_reference ? `${button('order-payment', 'Record collected payment', '', `data-ref="${e(order.reference)}"`)}${button('cancel-order', 'Cancel unpaid order', 'danger', `data-ref="${e(order.reference)}"`)}` : ''}</div></section>` : '';
  return `${heading(orderNumber(order), `${order.fulfillment} · ${orderStatus(order)} · ${order.sale_reference ? 'Paid' : 'Unpaid'}`, `<div class="actions">${routeLink('orders', `${icon('back')} Back to orders`)}${canWork && ['preparing', 'ready'].includes(order.status) ? button('edit-order', 'Edit order', 'secondary', `data-ref="${e(order.reference)}"`) : ''}</div>`)}${statusBadge(order.local_status)}${active ? `<ol class="progress" aria-label="Fulfillment progress">${sequence.map((status, index) => `<li${order.status === status ? ' aria-current="step"' : ''}><span aria-hidden="true">${index + 1}</span>${status === 'completed' ? order.fulfillment === 'delivery' ? 'Delivered' : 'Picked up' : status === 'out_for_delivery' ? 'Out for delivery' : status === 'ready' ? 'Ready' : 'Preparing'}</li>`).join('')}</ol>` : ''}<div class="order-layout"><section class="panel"><div class="panel-heading"><h2>Customer & preparation</h2></div><dl class="details"><div><dt>Customer</dt><dd>${e(order.customer_name)}</dd></div><div><dt>Contact</dt><dd>${e(order.customer_phone)}</dd></div>${order.fulfillment === 'delivery' ? `<div><dt>Delivery address</dt><dd>${e(order.delivery_address)}</dd></div>` : ''}<div><dt>Payment timing</dt><dd>${order.payment_plan === 'prepaid' ? 'Prepaid' : 'On collection'}</dd></div><div><dt>Original recorder</dt><dd>${e(nameOf(order.user_id))}</dd></div>${order.assigned_cashier_id ? `<div><dt>Assigned cashier</dt><dd>${e(nameOf(order.assigned_cashier_id))}</dd></div><div><dt>Assigned by</dt><dd>${e(nameOf(order.assigned_by))} · ${e(when(order.assigned_at))}</dd></div>` : ''}${order.paid_by ? `<div><dt>Payment recorded by</dt><dd>${e(nameOf(order.paid_by))}</dd></div>` : ''}<div><dt>Notes</dt><dd>${e(order.notes || 'No additional notes.')}</dd></div></dl><div class="table-wrap" tabindex="0" role="region" aria-label="Order items"><table><thead><tr><th>Item</th><th>Quantity</th><th>Amount</th></tr></thead><tbody>${order.items.map(line => `<tr><td><strong>${e(line.name)}</strong><small class="cell-sub">${e(line.sku)} · ${money(line.price_cents)} each</small></td><td>${line.quantity}</td><td class="money">${money(line.total_cents)}</td></tr>`).join('')}</tbody></table></div><div class="checkout-footer"><div class="breakdown"><span>Items subtotal</span><strong>${money(order.subtotal_cents)}</strong></div><div class="breakdown"><span>Delivery fee</span><strong>${money(order.delivery_fee_cents)}</strong></div><div class="total-row"><span>Total</span><strong>${money(order.total_cents)}</strong></div>${order.sale_reference ? routeLink(`receipt/${order.sale_reference}`, 'View paid receipt', 'button secondary full') : '<p class="help">Unpaid reserved quantities are excluded from paid sales.</p>'}</div></section><div>${!admin && active ? `<section class="panel"><div class="panel-heading"><h2>Device claim</h2></div><div class="panel-body form-stack"><p class="help">${leased ? 'This device can save authorized order changes offline.' : order.device_id ? 'Another device has this order. It must sync and release the claim before you can work on it here.' : 'Connect and claim this order before making changes on this device.'}</p>${leased ? button('release-order', 'Release this device’s claim', 'secondary', `data-ref="${e(order.reference)}"${disabled(!cleanOnline())}`) : !order.device_id ? button('claim-order', 'Claim on this device', '', `data-ref="${e(order.reference)}"${disabled(!cleanOnline())}`) : ''}</div></section>` : ''}${mutationActions}${handoff ? `<section class="panel"><div class="panel-heading"><h2>Hand off to cashier</h2></div><div class="panel-body"><p class="help">Internet and a fully synchronized device are required. Original recording and payment attribution remain unchanged. The working device must release its claim before reassignment.</p>${order.device_id ? '<p class="lease-note">This order is claimed. Ask the current device owner to sync and release it.</p>' : `<form id="handoff-form" class="form-stack" data-ref="${e(order.reference)}" data-version="${order.version}"><label for="handoff-cashier">Cashier handling this order<select id="handoff-cashier" name="assigned_cashier_id" required><option value="">Choose an active cashier</option>${s.cashiers.filter(staff => staff.active && staff.role === 'cashier').map(staff => `<option value="${staff.id}">${e(staff.name)}</option>`).join('')}</select></label><button class="button" type="submit"${disabled(!cleanOnline())}>Hand off order</button></form>`}</div></section>` : ''}${admin && !handoff ? '<section class="panel"><div class="panel-body"><p>Admin reviews recorded payments and fulfillment. Cashiers handle transaction actions.</p></div></section>' : ''}</div></div>`;
}

const operationNames: Record<MutationKind, string> = { 'sale.create': 'Counter sale', 'order.create': 'Customer order', 'order.edit': 'Order correction', 'order.payment': 'Collected payment', 'order.status': 'Fulfillment update', 'inventory.save': 'Inventory item', 'inventory.movement': 'Stock movement', 'order.handoff': 'Cashier handoff' };
function device() {
  const s = snapshot(); const events = store!.events;
  const quotas = s.allocations.map(allocation => { const product = s.products.find(item => item.id === allocation.product_id); const grant = s.price_grants.find(item => item.product_id === allocation.product_id && item.price_version_id === allocation.price_version_id); return `<tr>${td('Product', `<strong>${e(grant?.name || product?.name || 'Unavailable item')}</strong><small class="cell-sub">Frozen price ${money(grant?.price_cents ?? product?.price_cents ?? 0)}</small>`, 'primary-cell')}${td('Remaining', String(allocation.remaining))}${td('Actions', s.staff.role === 'cashier' ? button('release-allocation', 'Return unused stock', 'secondary', `data-id="${allocation.product_id}"${disabled(!cleanOnline() || cart.size > 0)}`) : 'Cashier-owned allocation', 'actions-cell')}</tr>`; });
  const reviewEntries = s.reviews.filter(review => !events.some(event => event.id === review.id));
  return `${heading('Device & sync', 'Keep track of this device’s saved work and shared stock access.')}<section class="metrics"><article class="metric featured"><span>Pending changes</span><strong>${store!.pendingCount}</strong><small>Durably saved on this device</small></article><article class="metric"><span>Review required</span><strong>${store!.reviewCount}</strong><small>Resolve the reported condition before retrying</small></article><article class="metric"><span>Connection</span><strong>${online() ? (autoSyncPaused ? 'Connection interrupted' : 'Online') : 'Offline'}</strong><small>Last cloud snapshot ${e(when(s.fetched_at))}</small></article><article class="metric"><span>Device</span><strong class="device-name-value">${e(s.device.name)}</strong><small>${e(s.device.id.slice(0, 8))} · ${e(s.staff.name)}</small></article></section><section class="panel"><div class="panel-heading"><div><h2>Saved changes</h2><p>Pending work remains on this device until confirmed by the cloud.</p></div>${button('sync', `${icon('sync')} Sync now`, '', disabled(!online() || busy))}</div><div class="panel-body"><p class="help">Do not clear browser storage or uninstall while changes are pending. Sign out and shared-stock releases remain blocked until pending work and reviews are resolved.</p></div>${table(['Change', 'Captured', 'Status', 'Details / actions'], events.map(event => `<tr>${td('Change', `<strong>${e(operationNames[event.kind])}</strong><small class="cell-sub">Sequence ${event.sequence}</small>`, 'primary-cell')}${td('Captured', e(when(event.captured_at)))}${td('Status', statusBadge(event.status))}${td('Details / actions', `<p>${e(event.message || 'Waiting for cloud confirmation.')}</p><small class="cell-sub">${e(eventSummary(event))}</small>${event.status === 'review' ? button('retry-review', 'Retry original change', 'secondary', `data-ref="${e(event.id)}"${disabled(!online() || busy)}`) : ''}`, 'actions-cell')}</tr>`), 'Saved synchronization changes')}${reviewEntries.length ? `<div class="panel-body form-stack"><h3>Other cloud reviews</h3>${reviewEntries.map(review => `<details class="review-details"><summary>${e(operationNames[review.kind as MutationKind] || review.kind)}</summary><p>${e(review.message)}</p><p class="help">Retry this change on the device that originally recorded it. The original receipt and payment reference must remain unchanged.</p></details>`).join('')}</div>` : ''}</section>${s.staff.role === 'cashier' ? `<section class="panel"><div class="panel-heading"><div><h2>This device’s remaining stock</h2><p>These allocated units cannot be sold by another disconnected device.</p></div></div>${table(['Product', 'Remaining', 'Actions'], quotas, 'This device’s stock allocations')}<div class="panel-body"><p class="help">Returning unused stock requires internet, no pending changes or reviews, and an empty POS basket. Existing unpaid orders keep their reservations.</p></div></section><section class="panel"><div class="panel-heading"><h2>Service & price access</h2></div><div class="panel-body form-stack"><p>Refresh approved service prices and product access after Admin changes inventory. Allocated product units keep their frozen price until returned.</p>${button('refresh-grants', 'Refresh service & price access', 'secondary', disabled(!cleanOnline() || cart.size > 0))}</div></section>` : ''}${installPrompt ? `<section class="panel"><div class="panel-body"><h2>Install this workspace</h2><p class="help">Use this browser’s installation option for quick access. Preparing a device and allocated stock are still required for offline work.</p>${button('install', 'Install app')}</div></section>` : ''}`;
}
function eventSummary(event: Mutation): string {
  const payload = event.payload as unknown as Record<string, unknown>;
  if (typeof payload.receipt_number === 'string') return `Receipt ${payload.receipt_number}`;
  if (typeof payload.reference === 'string') return `Order ${payload.reference.slice(0, 8).toUpperCase()}`;
  if (typeof payload.name === 'string') return `Item: ${payload.name}`;
  if (typeof payload.product_id === 'number') return `Item #${payload.product_id} · quantity ${payload.quantity}`;
  return 'Original change retained for audit';
}
let dialogOrigin: HTMLElement | null = null;
function closeDialog() { document.querySelectorAll<HTMLDialogElement>('dialog[open]').forEach(dialog => dialog.close()); }
function openDialog(title: string, body: string, origin: HTMLElement | null = document.activeElement as HTMLElement | null) {
  const dialog = document.getElementById('action-dialog') as HTMLDialogElement; if (!dialog) return;
  dialogOrigin = origin;
  dialog.innerHTML = `<div class="dialog-heading"><h2 id="dialog-title">${e(title)}</h2><button type="button" class="icon-button" data-action="close-dialog" aria-label="Close ${e(title)}">${icon('close')}</button></div><div class="dialog-feedback" aria-live="polite"></div>${body}`;
  dialog.addEventListener('close', () => { const target = dialogOrigin; if (target?.isConnected && target.getClientRects().length) target.focus({preventScroll: true}); }, {once: true});
  dialog.showModal();
}
const formFooter = (label: string) => `<div class="form-footer">${button('close-dialog', 'Cancel', 'secondary')}<button type="submit" class="button">${e(label)}</button></div>`;
const field = (id: string, label: string, value = '', attributes = '', name = id) => `<div><label for="${e(id)}">${e(label)}</label><input id="${e(id)}" name="${e(name)}" value="${e(value)}" ${attributes}></div>`;
const area = (id: string, label: string, value = '', attributes = '', name = id) => `<div class="wide"><label for="${e(id)}">${e(label)}</label><textarea id="${e(id)}" name="${e(name)}" ${attributes}>${e(value)}</textarea></div>`;
