function orderEditDialog(order: Order) {
  if (!editableHere(order) || !['preparing', 'ready'].includes(order.status)) throw new Error('Claim an editable order on this device before correcting it.');
  editOrder = structuredClone(order);
  editedLines = new Map(order.items.map(line => [line.product_id, {product_id: line.product_id, quantity: line.quantity, price_version_id: line.price_version_id}]));
  const paid = !!order.sale_reference;
  openDialog(`Edit ${orderNumber(order)}`, `<form id="order-edit-form" data-ref="${e(order.reference)}"><p class="lease-note">${paid ? 'Paid order: correct customer details only. Items, fulfillment, payment, and amounts remain frozen.' : 'Retained items keep their saved prices. Added items use this device’s approved price and stock.'}</p><div class="form-grid">${field('edit-customer-name', 'Customer name', order.customer_name, 'required maxlength="100"', 'customer_name')}${field('edit-customer-phone', 'Contact number', order.customer_phone, 'required type="tel" minlength="7" maxlength="30" inputmode="tel"', 'customer_phone')}${order.fulfillment === 'delivery' ? `${area('edit-address', 'Delivery address', order.delivery_address, 'required maxlength="300"', 'delivery_address')}${field('edit-fee', 'Delivery fee (₱)', (order.delivery_fee_cents / 100).toFixed(2), `type="number" min="0" max="99999.99" step="0.01" required${paid ? ' readonly' : ''}`, 'delivery_fee')}` : ''}${area('edit-notes', 'Order notes', order.notes, 'maxlength="500"', 'notes')}</div><h3 class="section-title">Order items</h3><div id="edited-lines">${editedLineMarkup()}</div>${paid ? '' : `<div class="item-picker"><label for="edit-add-item">Add a product or service<select id="edit-add-item"><option value="">Choose an item</option>${snapshot().products.filter(product => product.id > 0 && product.active && product.kind !== 'consumable' && grantFor(product) && available(product, grantFor(product)?.price_version_id) > 0).map(product => `<option value="${product.id}">${e(grantFor(product)?.name || product.name)} · ${money(grantFor(product)?.price_cents || product.price_cents)}</option>`).join('')}</select></label>${button('edit-add-line', `${icon('plus')} Add item`, 'secondary')}</div>`}${formFooter('Save order corrections')}</form>`);
}
function editedLineMarkup() {
  const order = editOrder!; const paid = !!order.sale_reference;
  return [...editedLines.values()].map(line => { const old = order.items.find(item => item.product_id === line.product_id); const product = snapshot().products.find(item => item.id === line.product_id)!; const grant = grantFor(product); const count = !product.active ? old?.quantity || 0 : Math.min(999, (old?.quantity || 0) + available(product, old ? undefined : line.price_version_id)); const name = old?.name || grant?.name || product.name; const price = old?.price_cents || grant?.price_cents || product.price_cents; return `<div class="line-editor"><div><strong>${e(name)}</strong><small>${money(price)} each · ${money(price * line.quantity)}</small></div><label class="sr-only" for="edit-quantity-${line.product_id}">Quantity of ${e(name)}</label><input id="edit-quantity-${line.product_id}" type="number" min="1" max="${paid ? line.quantity : count}" value="${line.quantity}" data-edit-id="${line.product_id}" required${paid ? ' readonly' : ''}>${paid ? '' : button('edit-remove-line', 'Remove', 'text-button', `data-id="${line.product_id}" aria-label="Remove ${e(name)} from order"`)}</div>`; }).join('') || empty('No items selected', 'Add at least one product or service before saving.');
}
function redrawEditedLines() { const region = document.getElementById('edited-lines'); if (region) region.innerHTML = editedLineMarkup(); }
function getOrder(reference: string): Order { const order = snapshot().orders.find(item => item.reference === reference); if (!order) throw new Error('This order is no longer available to your account. Refresh before continuing.'); return order; }
function getProduct(id: number): Product { const product = snapshot().products.find(item => item.id === id); if (!product) throw new Error('The item is unavailable. Refresh before continuing.'); return product; }
function requireOnline() { if (!online()) throw new Error('Reconnect to complete this shared online action. Your saved changes remain on this device.'); }
async function sharedAction(callback: (service: Backend) => Promise<void>) { requireOnline(); await store!.onlineAction(callback); }
async function enqueue<K extends MutationKind>(kind: K, payload: Payloads[K]): Promise<void> { await store!.enqueue(kind, payload); }
function noticeFailure(error: unknown) {
  const message = error instanceof Error ? error.message : 'The action could not be completed. Your saved work is retained.';
  report(message, true);
  const dialog = document.getElementById('action-dialog') as HTMLDialogElement | null;
  const status = dialog?.open && dialog.querySelector('.dialog-feedback');
  if (status) { status.innerHTML = `<div class="notice error" role="alert">${e(message)}</div>`; status.scrollIntoView({block: 'nearest'}); }
}
async function perform(action: () => Promise<void>, message = '', options: {close?: boolean; render?: boolean} = {}) {
  if (busy) return;
  busy = true;
  const activeForm = (document.activeElement as HTMLElement | null)?.closest('form') || document.querySelector('#action-dialog[open] form');
  const submit = activeForm?.querySelector<HTMLButtonElement>('[type=submit]'); if (submit) submit.disabled = true;
  try { await action(); if (message) report(message); if (options.close) closeDialog(); }
  catch (error) { noticeFailure(error); }
  finally { busy = false; if (submit?.isConnected) submit.disabled = false; const dialog = document.getElementById('action-dialog') as HTMLDialogElement | null; if (options.render !== false && !dialog?.open) render(); else updateSyncStatus(); }
}
function updateSyncStatus() { const region = document.getElementById('sync-status'); if (region && store?.snapshot && authorized) region.innerHTML = syncStatus(); }
async function syncNow(silent = false) {
  requireOnline();
  const result = await store!.sync();
  if (!store!.snapshot) { authorized = false; throw new Error(result.transportError || 'Sign in again with this device’s account. Your pending work is retained.'); }
  if (result.transportError) { autoSyncPaused = true; throw new Error(result.transportError); }
  autoSyncPaused = false;
  if (result.synced || result.pending || store!.reviewCount) report(`${result.synced} change${result.synced === 1 ? '' : 's'} confirmed. ${result.pending} pending${store!.reviewCount ? `; ${store!.reviewCount} require review` : ''}.`, store!.reviewCount > 0);
  else if (!silent) feedback = {text: '', error: false};
}
function paymentFrom(data: FormData, due: number): Payment {
  const method = data.get('payment_method'); if (method !== 'cash' && method !== 'gcash') throw new Error('Choose cash or GCash.');
  const amount = parseMoney(String(data.get('amount') || ''));
  if (method === 'cash' && amount < due) throw new Error('Cash received is below the total due.');
  if (method === 'gcash') { const reference = String(data.get('payment_reference') || '').trim().toUpperCase(); if (amount !== due || data.get('payment_verified') !== 'on' || !/^[A-Z0-9-]{6,80}$/.test(reference)) throw new Error('Verify the exact GCash amount and reference in the store account before recording this payment.'); return {method, amount_cents: amount, reference, verified: true}; }
  return {method, amount_cents: amount};
}
function resetCart() { const form = document.getElementById('pos-form'); if (form) form.dataset.completed = 'true'; cart.clear(); Object.assign(pos, {fulfillment: 'counter', channel: 'walk-in', payment_plan: 'prepaid', customer_name: '', customer_phone: '', delivery_address: '', notes: '', delivery_fee: '0.00', payment_method: 'cash', amount: '', payment_reference: '', payment_verified: false}); posPane = 'products'; }
function setCartQuantity(id: number, count: number) {
  const line = cart.get(id); if (!line) return;
  const product = getProduct(id), maximum = Math.min(999, available(product, line.price_version_id));
  if (!Number.isInteger(count) || count < 1 || count > maximum) throw new Error(`Choose 1–${maximum} units of ${line.name}. Ask Admin for more allocated stock if needed.`);
  line.quantity = count; line.total_cents = count * line.price_cents;
}
function addProduct(id: number) {
  const product = getProduct(id), grant = grantFor(product); if (!product.active || product.kind === 'consumable' || !grant) throw new Error('This item is not approved for sale on this device.');
  if (cart.has(id)) { setCartQuantity(id, cart.get(id)!.quantity + 1); return; }
  if (available(product, grant.price_version_id) < 1) throw new Error('No remaining stock is allocated to this device for this item.');
  if (cart.size >= 100) throw new Error('A transaction can contain at most 100 different items.');
  cart.set(id, {...grant, quantity: 1, total_cents: grant.price_cents});
}
function showPosPane(pane: 'products' | 'sale', focus = false) {
  capturePos(); posPane = pane;
  const layout = document.querySelector<HTMLElement>('.pos-layout'); if (layout) layout.dataset.pane = pane;
  document.querySelectorAll<HTMLButtonElement>('.pos-view-switcher [role=tab]').forEach(tab => { const active = tab.id === `${pane === 'sale' ? 'sale' : 'products'}-tab`; tab.setAttribute('aria-selected', String(active)); tab.tabIndex = active ? 0 : -1; });
  const bar = document.querySelector<HTMLElement>('.mobile-sale-bar'); if (bar) bar.hidden = pane === 'sale';
  if (focus) document.getElementById(pane === 'sale' ? 'sale-tab' : 'products-tab')?.focus({preventScroll: true});
}

async function handleClick(event: MouseEvent) {
  const element = (event.target as Element).closest<HTMLElement>('[data-action],[data-route]'); if (!element || element instanceof HTMLButtonElement && element.disabled) return;
  if (element.dataset.route !== undefined) { event.preventDefault(); if (authorized && store?.snapshot) go(element.dataset.route); else location.href = '/'; return; }
  const action = element.dataset.action!, id = Number(element.dataset.id), reference = element.dataset.ref || '';
  try {
    if (action === 'menu') { (document.getElementById('store-menu') as HTMLDialogElement).showModal(); return; }
    if (action === 'close-menu') { (document.getElementById('store-menu') as HTMLDialogElement).close(); return; }
    if (action === 'close-dialog') { (document.getElementById('action-dialog') as HTMLDialogElement).close(); return; }
    if (action === 'print') { window.print(); return; }
    if (action === 'reset-sales') { salesFrom = ''; salesTo = ''; render(); return; }
    if (action === 'pos-products' || action === 'pos-sale') { showPosPane(action === 'pos-sale' ? 'sale' : 'products', element.closest('.pos-view-switcher') !== null); return; }
    if (action === 'customer-details') { capturePos(); customerDialog(); return; }
    if (action === 'add-product') { capturePos(); addProduct(id); render(); return; }
    if (action === 'cart-plus' || action === 'cart-minus') { capturePos(); const quantity = cart.get(id)!.quantity + (action === 'cart-plus' ? 1 : -1); if (quantity === 0) cart.delete(id); else setCartQuantity(id, quantity); render(); return; }
    if (action === 'cart-remove') { capturePos(); cart.delete(id); render(); return; }
    if (action === 'clear-cart') { capturePos(); openDialog('Clear current basket?', `<p>Remove all selected items from this unrecorded transaction? Customer and payment details remain until you complete or reset the sale.</p><div class="form-footer">${button('close-dialog', 'Keep basket', 'secondary')}${button('confirm-clear', 'Clear basket', 'danger')}</div>`); return; }
    if (action === 'confirm-clear') { cart.clear(); closeDialog(); render(); return; }
    if (action === 'pos-filter') { typeFilter = element.dataset.filter!; render(); return; }
    if (action === 'inventory-items' || action === 'inventory-movements') { inventoryTab = action === 'inventory-items' ? 'items' : 'movements'; render(); return; }
    if (action === 'new-product') { inventoryDialog(); return; }
    if (action === 'edit-product') { inventoryDialog(getProduct(id)); return; }
    if (action === 'stock-movement') { movementDialog(getProduct(id)); return; }
    if (action === 'new-cashier') { cashierDialog('create'); return; }
    if (action === 'edit-cashier') { cashierDialog('edit', id); return; }
    if (action === 'cashier-password') { cashierDialog('password', id); return; }
    if (action === 'cashier-active') { cashierDialog('active', id); return; }
    if (action === 'edit-order') { orderEditDialog(getOrder(reference)); return; }
    if (action === 'order-payment') { orderPaymentDialog(getOrder(reference)); return; }
    if (action === 'cancel-order') { cancelDialog(getOrder(reference)); return; }
    if (action === 'edit-remove-line') { editedLines.delete(id); redrawEditedLines(); return; }
    if (action === 'edit-add-line') { const value = Number((document.getElementById('edit-add-item') as HTMLSelectElement).value); if (!value) throw new Error('Choose an item to add.'); const old = editOrder!.items.find(line => line.product_id === value); const product = getProduct(value), grant = grantFor(product); if (!grant) throw new Error('This item has no approved price grant.'); if (editedLines.has(value)) throw new Error('This item is already listed. Change its quantity above.'); editedLines.set(value, {product_id: value, quantity: 1, price_version_id: old?.price_version_id || grant.price_version_id}); redrawEditedLines(); return; }
    if (action === 'sync') { await perform(() => syncNow()); return; }
    if (action === 'reauth') { lastKnown = snapshot(); authorized = false; closeDialog(); render(); return; }
    if (action === 'signout') { await perform(async () => { if (cart.size) throw new Error('Clear or record the current POS basket before signing out.'); requireOnline(); await store!.signOut(); authorized = false; lastKnown = null; resetCart(); location.hash = ''; }, 'Signed out.'); return; }
    if (action === 'claim-order') { await perform(() => sharedAction(service => service.claimOrder(snapshot().device.id, reference)), 'Order claimed on this device. You can now save its authorized changes offline.'); return; }
    if (action === 'release-order') { await perform(() => sharedAction(service => service.releaseOrder(snapshot().device.id, reference)), 'Device claim released. Another authorized device can claim this order.'); return; }
    if (action === 'order-status') { const order = getOrder(reference); const status = element.dataset.status as Order['status']; await perform(() => enqueue('order.status', {reference, expected_version: order.version, status}), 'Fulfillment update saved on this device.'); kickSync(); return; }
    if (action === 'refresh-grants') { await perform(async () => { if (cart.size) throw new Error('Clear or record the POS basket before refreshing price access.'); const s = snapshot(); await sharedAction(service => service.refreshPriceGrants(s.device.id, s.device.next_sequence)); }, 'Service and price access refreshed.'); return; }
    if (action === 'release-allocation') { openDialog('Return unused allocated stock?', `<p>Return this device’s remaining allocation for ${e(getProduct(id).name)} to free store stock? Reserved customer orders keep their quantities.</p><form id="release-allocation-form" data-id="${id}">${formFooter('Return unused stock')}</form>`); return; }
    if (action === 'retry-review') { reviewDialog(reference); return; }
    if (action === 'install') { const prompt = installPrompt; if (!prompt) return; await prompt.prompt(); await prompt.userChoice; installPrompt = null; render(); return; }
  } catch (error) { noticeFailure(error); if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); }
}

async function handleSubmit(event: SubmitEvent) {
  const form = event.target as HTMLFormElement; if (!form.matches('form')) return; event.preventDefault(); if (busy) return;
  const data = new FormData(form); const value = (name: string) => String(data.get(name) || '').trim();
  const reference = form.dataset.ref || '';
  if (!form.checkValidity()) { form.reportValidity(); return; }
  if (form.id === 'signin-form') { await perform(() => signIn(data)); return; }
  if (form.id === 'customer-form') {
    try { if (pos.fulfillment === 'delivery') parseMoney(value('delivery_fee')); Object.assign(pos, {customer_name: value('customer_name'), customer_phone: value('customer_phone'), notes: value('notes'), ...(pos.fulfillment === 'delivery' ? {delivery_address: value('delivery_address'), delivery_fee: value('delivery_fee')} : {})}); closeDialog(); render(); } catch (error) { noticeFailure(error); } return;
  }
  if (form.id === 'pos-form') {
    capturePos();
    if (pos.fulfillment !== 'counter' && (!pos.customer_name || !pos.customer_phone || pos.fulfillment === 'delivery' && !pos.delivery_address)) { if (narrow()) showPosPane('sale'); customerDialog(); noticeFailure(new Error('Complete the customer details before confirming this order.')); return; }
    await perform(async () => {
      if (!cart.size) throw new Error('Add at least one product or service.'); const ref = uuid(); const number = receiptNumber(ref);
      if (pos.fulfillment === 'counter') { await enqueue('sale.create', {reference: ref, receipt_number: number, channel: pos.channel, items: lines(), payment: paymentFrom(data, total())}); resetCart(); report('Sale saved on this device. Its receipt remains pending until cloud confirmation.'); go(`receipt/${ref}`); }
      else { const input: Payloads['order.create'] = {reference: ref, receipt_number: number, channel: pos.channel, fulfillment: pos.fulfillment as 'pickup' | 'delivery', payment_plan: pos.payment_plan as 'prepaid' | 'collection', customer_name: pos.customer_name, customer_phone: pos.customer_phone, delivery_address: pos.fulfillment === 'delivery' ? pos.delivery_address : '', notes: pos.notes, delivery_fee_cents: pos.fulfillment === 'delivery' ? parseMoney(pos.delivery_fee) : 0, items: lines()}; if (pos.payment_plan === 'prepaid') input.payment = paymentFrom(data, total()); await enqueue('order.create', input); resetCart(); report('Order saved and claimed on this device. Synchronize to confirm it in the cloud.'); go(`order/${ref}`); }
    }); kickSync(); return;
  }
  if (form.id === 'inventory-form') {
    const product = form.dataset.id ? getProduct(Number(form.dataset.id)) : undefined;
    await perform(async () => { const kind = product?.kind || value('kind') as Kind; const input: Payloads['inventory.save'] = {sku: value('sku'), name: value('name'), category: value('category'), kind, price_cents: kind === 'consumable' ? 0 : parseMoney(value('price')), reorder_level: Number(value('reorder_level')), active: data.get('active') === 'on', description: value('description')}; if (product) { input.id = product.id; input.expected_version = Number(form.dataset.version); if (product.client_reference) input.client_reference = product.client_reference; } else input.client_reference = uuid(); await enqueue('inventory.save', input); }, 'Inventory item saved on this device.', {close: true}); kickSync(); return;
  }
  if (form.id === 'movement-form') { const product = getProduct(Number(form.dataset.id)); await perform(() => enqueue('inventory.movement', {product_id: product.id, ...(product.client_reference ? {product_reference: product.client_reference} : {}), quantity: Number(value('quantity')) * (value('direction') === 'use' ? -1 : 1), reason: value('reason')}), 'Stock movement saved on this device.', {close: true}); kickSync(); return; }
  if (form.id === 'cashier-form') {
    const action = form.dataset.kind as 'create' | 'edit' | 'password' | 'active'; const id = Number(form.dataset.id);
    await perform(async () => { const input: Record<string, unknown> = action === 'create' ? {} : {staff_id: id}; if (action === 'edit' || action === 'create') Object.assign(input, {name: value('name'), email: value('email')}); if (action === 'password' || action === 'create') { const password = String(data.get('password') || ''), confirmation = String(data.get('password_confirmation') || ''); if (password !== confirmation) throw new Error('The password confirmation does not match.'); Object.assign(input, {password, password_confirmation: confirmation}); } if (action === 'active') input.active = form.dataset.active === 'true'; await sharedAction(service => service.staffAction(action, input)); form.reset(); }, 'Cashier account updated.', {close: true}); return;
  }
  if (form.id === 'allocation-form') { await perform(() => sharedAction(service => service.allocate(value('device_id'), Number(value('product_id')), Number(value('quantity')))), 'Stock allocated to the selected cashier device.'); return; }
  if (form.id === 'release-allocation-form') { await perform(async () => { if (cart.size) throw new Error('Clear or record the current basket before returning stock.'); await sharedAction(service => service.releaseAllocation(snapshot().device.id, Number(form.dataset.id))); }, 'Unused stock returned to the store.', {close: true}); return; }
  if (form.id === 'handoff-form') {
    const order = getOrder(reference), cashierId = Number(value('assigned_cashier_id'));
    await perform(async () => {
      requireOnline();
      if (!store!.canSignOut || store!.requiresRefresh) throw new Error('Sync and resolve this device’s pending work before handing off an order.');
      if (order.device_id) throw new Error('The current device owner must sync and release this order’s claim before handoff.');
      const event = await store!.enqueue('order.handoff', {reference, expected_version: Number(form.dataset.version || order.version), assigned_cashier_id: cashierId});
      report('Handoff saved on this device. Waiting for cloud confirmation.'); render();
      const result = await store!.sync();
      const outstanding = store!.events.find(record => record.id === event.id);
      if (outstanding?.status === 'review') throw new Error(`Handoff requires review: ${outstanding.message || 'Review the current assignment and device claim before retrying.'}`);
      if (result.transportError || outstanding) throw new Error(`Handoff is not yet confirmed in the cloud. Select Sync now after reconnecting. ${result.transportError || 'The assignment remains pending on this device.'}`);
      const confirmed = store!.snapshot?.orders.find(record => record.reference === reference);
      if (!confirmed || confirmed.local_status || confirmed.assigned_cashier_id !== cashierId) throw new Error('Refresh and review this order before treating its handoff as confirmed.');
      report(`Handoff confirmed in the cloud. ${nameOf(cashierId)} is assigned to this order.`);
    }); return;
  }
  if (form.id === 'order-payment-form') { const order = getOrder(reference); await perform(() => enqueue('order.payment', {reference, expected_version: Number(form.dataset.version), receipt_number: receiptNumber(uuid()), payment: paymentFrom(data, order.total_cents)}), 'Collected payment saved on this device.', {close: true}); kickSync(); return; }
  if (form.id === 'cancel-form') { await perform(() => enqueue('order.status', {reference, expected_version: Number(form.dataset.version), status: 'cancelled', cancel_reason: value('reason'), goods_returned: data.get('goods_returned') === 'on'}), 'Order cancellation saved on this device.', {close: true}); kickSync(); return; }
  if (form.id === 'order-edit-form') { const order = editOrder!; await perform(() => enqueue('order.edit', {reference, expected_version: order.version, customer_name: value('customer_name'), customer_phone: value('customer_phone'), delivery_address: order.fulfillment === 'delivery' ? value('delivery_address') : '', notes: value('notes'), delivery_fee_cents: order.fulfillment === 'delivery' ? parseMoney(value('delivery_fee')) : 0, items: [...editedLines.values()]}), 'Order corrections saved on this device.', {close: true}); kickSync(); return; }
  if (form.id === 'sales-filter') { salesFrom = value('from'); salesTo = value('to'); if (salesFrom && salesTo && salesFrom > salesTo) report('The From date must be on or before the To date.', true); render(); return; }
  if (form.id === 'review-retry-form') { await perform(() => retryCorrection(reference, data.get('refresh_version') === 'on'), 'Original details queued for another cloud review.', {close: true}); kickSync(); return; }
  if (form.id === 'review-resolve-form') { await perform(async () => { requireOnline(); await store!.resolveReview(reference, value('replacement_id'), value('note')); }, 'Review linked to the confirmed correction.', {close: true}); return; }
}

app.addEventListener('click', event => { void handleClick(event); });
app.addEventListener('submit', event => { void handleSubmit(event as SubmitEvent).catch(error => { noticeFailure(error); }); });
app.addEventListener('input', event => {
  const input = event.target as HTMLInputElement; if (!input.matches('input')) return;
  if (input.id === 'pos-search' || input.id === 'inventory-search') { searchText = input.value; render(); }
  else if (input.id === 'order-search') { orderSearch = input.value; render(); }
  else if (input.id === 'pos-amount') { capturePos(); const change = document.getElementById('cart-change'); if (change) change.textContent = money(Math.max(0, safeMoney(pos.amount) - total())); }
});
app.addEventListener('change', event => {
  const input = event.target as HTMLInputElement | HTMLSelectElement;
  try {
    if (input.dataset.cartId) { setCartQuantity(Number(input.dataset.cartId), Number(input.value)); render(); }
    else if (input.dataset.editId) { const line = editedLines.get(Number(input.dataset.editId)); if (line) { line.quantity = Number(input.value); redrawEditedLines(); } }
    else if (['pos-fulfillment', 'pos-channel', 'pos-payment-plan', 'pos-payment-method'].includes(input.id)) { capturePos(); render(); }
    else if (input.id === 'order-filter') { orderFilter = input.value; render(); }
    else if (input.id === 'item-kind') { const price = document.getElementById('item-price') as HTMLInputElement; price.readOnly = input.value === 'consumable'; price.min = price.readOnly ? '0' : '0.01'; if (price.readOnly) price.value = '0.00'; }
    else if (input.id === 'collected-payment-method') { const form = input.closest('form')!; const gcash = form.querySelector<HTMLElement>('.gcash-fields')!; const selectedGcash = input.value === 'gcash'; gcash.hidden = !selectedGcash; gcash.querySelectorAll<HTMLInputElement>('input').forEach(field => { field.disabled = !selectedGcash; field.required = selectedGcash; }); const amountLabel = form.querySelector<HTMLLabelElement>('label[for=collected-amount]')!; amountLabel.firstChild!.textContent = selectedGcash ? 'Verified GCash amount (₱)' : 'Cash received (₱)'; }
  } catch (error) { noticeFailure(error); if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); }
});
app.addEventListener('keydown', event => {
  const target = event.target as HTMLElement;
  if (target.closest('.pos-view-switcher') && ['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) { event.preventDefault(); showPosPane(event.key === 'Home' ? 'products' : event.key === 'End' ? 'sale' : posPane === 'products' ? 'sale' : 'products', true); }
});

function matchingDetails(left: Mutation, right: Mutation): boolean {
  if (left.kind !== right.kind || left.captured_at !== right.captured_at) return false;
  const canonical = (payload: unknown) => JSON.stringify(Object.fromEntries(Object.entries(payload as Record<string, unknown>).filter(([key]) => key !== 'expected_version').sort(([a], [b]) => a.localeCompare(b))));
  return canonical(left.payload) === canonical(right.payload);
}
function reviewDialog(id: string) {
  const original = store!.events.find(event => event.id === id && event.status === 'review'); if (!original) throw new Error('This review must be retried on its original device.');
  const payload = original.payload as unknown as Record<string, unknown>;
  let version: number | undefined;
  if (typeof payload.expected_version === 'number') {
    if (original.kind.startsWith('order.')) version = snapshot().orders.find(order => order.reference === payload.reference)?.version;
    if (original.kind === 'inventory.save') version = snapshot().products.find(product => product.id === payload.id || payload.client_reference && product.client_reference === payload.client_reference)?.version;
  }
  const candidates = store!.syncedEvents.filter(event => matchingDetails(original, event));
  openDialog(`Review · ${operationNames[original.kind]}`, `<p class="notice error">${e(original.message || 'The cloud could not accept this change.')}</p><p>${e(eventSummary(original))}</p><p class="help">Correct the reported condition first. A retry preserves the original item prices, quantities, receipt, payment reference, and captured business date. A previously rejected change is not silently counted as cloud-confirmed.</p>${candidates.length ? `<form id="review-resolve-form" data-ref="${e(id)}" class="form-stack"><h3>Link a confirmed correction</h3><label for="review-replacement">Confirmed matching change<select id="review-replacement" name="replacement_id" required><option value="">Choose the confirmed correction</option>${candidates.map(event => `<option value="${e(event.id)}">Sequence ${event.sequence} · ${e(when(event.captured_at))}</option>`).join('')}</select></label>${area('review-note', 'Review resolution note', '', 'required maxlength="300"', 'note')}${formFooter('Resolve with confirmed correction')}</form>` : `<form id="review-retry-form" data-ref="${e(id)}"><p class="help">The original captured record remains available for audit.</p>${version !== undefined && version !== payload.expected_version ? `<label class="checkbox-label"><input type="checkbox" name="refresh_version"> I reviewed the current record and approve retrying these same details against version ${version}.</label><p class="help">Only the record version changes. Financial details, references, and the business date remain exactly as captured. A successful retry links the confirmed correction to this review.</p>` : ''}${formFooter('Retry unchanged details')}</form>`}`);
}
async function retryCorrection(id: string, refreshedVersion: boolean) {
  requireOnline();
  await store!.retryReview(id, refreshedVersion);
}

async function signIn(data: FormData) {
  requireOnline(); if (!backend || !store) throw new Error('Configure the cloud connection before staff sign-in.');
  if (store.signOutPending) throw new Error('Finish the interrupted sign out before preparing this device again.');
  const expected = store.preparedIdentity;
  const staff = await backend.signIn(String(data.get('email') || '').trim(), String(data.get('password') || ''));
  if (expected && expected.staffId !== staff.id) { await backend.signOut(); throw new Error('Use this prepared device’s original staff account. Its saved changes have been retained.'); }
  let deviceId = expected?.deviceId || localStorage.getItem(deviceIdKey);
  const previousStaff = localStorage.getItem(deviceStaffKey);
  if (!deviceId || !/^[0-9a-f-]{36}$/i.test(deviceId) || !expected && previousStaff !== String(staff.id)) deviceId = uuid();
  localStorage.setItem(deviceIdKey, deviceId);
  localStorage.setItem(deviceStaffKey, String(staff.id));
  const deviceName = expected?.name || String(data.get('device_name') || '').trim();
  if (!deviceName) throw new Error('Give this device a recognizable name.');
  await backend.registerDevice(deviceName, deviceId);
  const fresh = await backend.snapshot(deviceId);
  if (fresh.staff.id !== staff.id || fresh.device.staff_id !== staff.id || fresh.device.id !== deviceId) throw new Error('The prepared device identity did not match this staff account.');
  await store.prepare(fresh); lastKnown = fresh; authorized = true;
  (document.getElementById('signin-form') as HTMLFormElement | null)?.reset();
  report('Device prepared. Allocated stock and claimed orders are available for authorized offline work.');
  if (!location.hash || ['overview', 'pos'].includes(location.hash.slice(1))) location.hash = staff.role === 'admin' ? 'overview' : 'pos';
  if (store.pendingCount || store.reviewCount) await syncNow();
}
let syncTimer = 0;
function kickSync() {
  if (!online() || autoSyncPaused || !authorized || !store?.snapshot) return;
  window.clearTimeout(syncTimer);
  syncTimer = window.setTimeout(() => { if (!busy && online() && authorized) void perform(() => syncNow(true)); }, 400);
}
function sessionChanged() {
  const current = store?.snapshot; if (current) lastKnown = current;
  else if (authorized) { authorized = false; closeDialog(); render(); return; }
  if (!busy && !(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render();
  else updateSyncStatus();
}
async function start() {
  registerPwa();
  if (!backend) { renderAuth(true); return; }
  try {
    store = await OfflineStore.open({backend, databaseName});
    store.subscribe(sessionChanged);
    const cached = store.snapshot;
    authorized = !!cached && cached.staff.id === getRememberedStaffId();
    if (cached) lastKnown = cached;
    if (authorized) { localStorage.setItem(deviceIdKey, cached!.device.id); localStorage.setItem(deviceStaffKey, String(cached!.staff.id)); }
    render();
    if (authorized && online()) kickSync();
  } catch (error) { noticeFailure(error); renderAuth(false); }
}
window.addEventListener('hashchange', () => { if (authorized) render(); });
window.addEventListener('online', () => { autoSyncPaused = false; if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); else updateSyncStatus(); kickSync(); });
window.addEventListener('offline', () => { if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); else updateSyncStatus(); });
window.addEventListener('beforeinstallprompt', event => { event.preventDefault(); installPrompt = event as typeof installPrompt; if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); });
window.addEventListener('appinstalled', () => { installPrompt = null; report('Workspace installed.'); if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); });
window.addEventListener('pwa-status', event => { report(String((event as CustomEvent).detail), true); if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); });
const compactQuery = window.matchMedia('(max-width:1100px)');
const paneQuery = window.matchMedia('(max-width:900px)');
compactQuery.addEventListener('change', () => { const menu = document.getElementById('store-menu') as HTMLDialogElement | null; if (!compactQuery.matches && menu?.open) menu.close(); });
paneQuery.addEventListener('change', () => { if (!(document.getElementById('action-dialog') as HTMLDialogElement | null)?.open) render(); });
app.addEventListener('invalid', event => { const field = event.target as HTMLElement; if (field.closest('#pos-form') && field.closest('#checkout-basket') && narrow()) showPosPane('sale'); }, true);
window.addEventListener('beforeunload', event => { if (store?.pendingCount || store?.reviewCount || cart.size) { event.preventDefault(); event.returnValue = ''; } });
void start();
